    AS SOURCE ([Id], [SolutionId], [TypeOfService], [ServiceLevel], [HowMeasured], [ServiceCredits], [LastUpdated], [LastUpdatedBy])
    ON TARGET.[Id] = SOURCE.[Id]
    WHEN MATCHED THEN UPDATE SET
        TARGET.[SolutionId] = SOURCE.[SolutionId],
        TARGET.[TypeOfService] = SOURCE.[TypeOfService],
        TARGET.[ServiceLevel] = SOURCE.[ServiceLevel],
        TARGET.[HowMeasured] = SOURCE.[HowMeasured],
        TARGET.[ServiceCredits] = SOURCE.[ServiceCredits],
        TARGET.[LastUpdated] = SOURCE.[LastUpdated],
        TARGET.[LastUpdatedBy] = SOURCE.[LastUpdatedBy]
    WHEN NOT MATCHED BY TARGET THEN
        INSERT ([Id], [SolutionId], [TypeOfService], [ServiceLevel], [HowMeasured], [ServiceCredits], [LastUpdated], [LastUpdatedBy])
        VALUES (SOURCE.[Id], SOURCE.[SolutionId], SOURCE.[TypeOfService], SOURCE.[ServiceLevel], SOURCE.[HowMeasured], SOURCE.[ServiceCredits], SOURCE.[LastUpdated], SOURCE.[LastUpdatedBy]);

    SET IDENTITY_INSERT [catalogue].[SlaServiceLevels] OFF
